# PMT Core Pure 2, Ch.5 Polar Coordinates: transcribed from the rendered page images. Wording, part labels and marks
# exactly as printed; figures are source crops with their printed captions. Q5 prints only the question total.
from lib import *
Q = {}
Q[1] = (fig(1, 85, 'Figure 1: polar sketch with pole O, the initial line and the half-line θ = π/2 dashed; the curve C runs from the half-line θ = π/2 down to the initial line, passing through A; N is on the initial line directly below A, and the region R between the curve, AN and the initial line is shaded')
        + p(f'The curve {m("C")} shown in Figure 1 has polar equation') + eq(r'r=4+\cos2\theta\qquad0\leqslant\theta\leqslant\frac{\pi}{2}')
        + p(f'At the point {m("A")} on {m("C")}, the value of {m("r")} is {m(r"\dfrac92")}')
        + p(f'The point {m("N")} lies on the initial line and {m("AN")} is perpendicular to the initial line.')
        + p(f'The finite region {m("R")}, shown shaded in Figure 1, is bounded by the curve {m("C")}, the initial line and the line {m("AN")}.')
        + p(f'Find the exact area of the shaded region {m("R")}, giving your answer in the form {m(r"p\pi+q\sqrt3")} where {m("p")} and {m("q")} are rational numbers to be found. {mk(9)}'))
Q[2] = (fig(2, 55, 'Figure 1: a closed curve around the pole O, roughly circular with a slight inward dent at the bottom, and the initial line drawn from O to the right')
        + p('Figure 1 shows a sketch of a curve with polar equation') + eq(r'r=6+a\sin\theta')
        + p(f'where {m("0<a<6")} and {m(r"0\leqslant\theta<2\pi")}')
        + p(f'The area enclosed by the curve is {m(r"\dfrac{97\pi}{2}")}')
        + p(f'Find the value of the constant {m("a")}. {mk(8)}'))
Q[3] = (fig(3, 65, 'Figure 1: pole O and the initial line; the curve C rises from the initial line, curving up to touch a vertical tangent line at A and then bending back to the left; the region R between the curve, the vertical tangent at A and the initial line is shaded')
        + p(f'Figure 1 shows a sketch of the curve {m("C")} with equation') + eq(r'r=1+\tan\theta\qquad\qquad0\leqslant\theta<\frac{\pi}{3}')
        + p(f'Figure 1 also shows the tangent to {m("C")} at the point {m("A")}.<br>This tangent is perpendicular to the initial line.')
        + parts([f'Use differentiation to prove that the polar coordinates of {m("A")} are {m(r"\left(2,\dfrac{\pi}{4}\right)")} {mk(4)}'], kind='a')
        + p(f'The finite region {m("R")}, shown shaded in Figure 1, is bounded by {m("C")}, the tangent at {m("A")} and the initial line.')
        + parts([f'Use calculus to show that the exact area of {m("R")} is {m(r"\dfrac12(1-\ln2)")} {mk(6)}'], start=2, kind='a'))
Q[4] = (fig(4, 115, 'Figure 1: rectangle ABCD with AB marked 1.2 m; inside it a white closed curve shaped like a figure-of-eight outline pinched at the top and bottom middle; the area between the curve and the rectangle is shaded; labelled "Diagram not to scale"')
        + p(f'Figure 1 shows the design for a table top in the shape of a rectangle {m("ABCD")}. The length of the table, {m("AB")}, is 1.2 m. The area inside the closed curve is made of glass and the surrounding area, shown shaded in Figure 1, is made of wood.')
        + p('The perimeter of the glass is modelled by the curve with polar equation') + eq(r'r=0.4+a\cos2\theta\qquad0\leqslant\theta<2\pi')
        + p(f'where {m("a")} is a constant.')
        + parts([f'Show that {m("a=0.2")} {mk(2)}'], kind='a')
        + p(f'Hence, given that {m("AD")} = 60 cm,')
        + parts([f'find the area of the wooden part of the table top, giving your answer in {m(r"\mathrm m^2")} to 3 significant figures. {mk(8)}'], start=2, kind='a'))
Q[5] = (fig(5, 80, 'Figure 1: the pole O with the initial line to the right; a small curve C1 above O and a large curve C2 mostly below O, both passing through O; the region R inside C1 and outside C2, above C2, is shaded')
        + p(f'Figure 1 shows a sketch of two curves {m("C_1")} and {m("C_2")} with polar equations')
        + eq(r'C_1\!:\ r=(1+\sin\theta)\qquad0\leqslant\theta<2\pi') + eq(r'C_2\!:\ r=3(1-\sin\theta)\qquad0\leqslant\theta<2\pi')
        + p(f'The region {m("R")} lies inside {m("C_1")} and outside {m("C_2")} and is shown shaded in Figure 1.')
        + p(f'Show that the area of {m("R")} is') + eq(r'p\sqrt3-q\pi') + p(f'where {m("p")} and {m("q")} are integers to be determined.'))
Q[6] = (parts([parts([p(f'Show on an Argand diagram the locus of points given by the values of {m("z")} satisfying') + eq(r'|z-4-3\mathrm i|=5')], kind='i')
               + p(f'Taking the initial line as the positive real axis with the pole at the origin and given that {m(r"\theta\in[\alpha,\alpha+\pi]")},<br>where {m(r"\alpha=-\arctan\left(\frac43\right)")},')
               + parts([p('show that this locus of points can be represented by the polar curve with equation') + eq(r'r=8\cos\theta+6\sin\theta')], start=2, kind='i') + mk(6)], kind='a')
        + p(f'The set of points {m("A")} is defined by') + eq(r'A=\left\{z:0\leqslant\arg z\leqslant\frac{\pi}{3}\right\}\cap\{z:|z-4-3\mathrm i|\leqslant5\}')
        + parts([parts([f'Show, by shading on your Argand diagram, the set of points {m("A")}.', f'Find the <strong>exact</strong> area of the region defined by {m("A")}, giving your answer in simplest form.'], kind='i') + mk(7)], start=2, kind='a'))
